import sys

data = sys.stdin.read().split()
s = data[0]
st = []
ok = True
for c in s:
    if c in "([":
        st.append(c)
    else:
        if not st or st.pop() != ("(" if c == ")" else "["):
            ok = False
            break
print("YES" if ok and not st else "NO")

